// Support for code generated by `solis --emit-c`. The generated file includes
// solis.c directly (so it can see the object layouts) and then this header.

#include <setjmp.h>

static jmp_buf aot_jb;

#define AOT_FAIL(...) do { vm_error(vm, __VA_ARGS__); longjmp(aot_jb, 1); } while (0)

#define AOT_LIKELY(x)   __builtin_expect(!!(x), 1)
#define AOT_UNLIKELY(x) __builtin_expect(!!(x), 0)

static inline sl_value aot_take(sl_value *p) { sl_value v = vload(p); moved(p); return v; }

static inline sl_arr *aot_arr(sl_vm *vm, sl_value v) {
    if (AOT_UNLIKELY(v.type != SL_OBJ || !v.as.o || v.as.o->kind != SL_ARRAY)) AOT_FAIL("not an array");
    return (sl_arr *)v.as.o;
}
static inline sl_struct *aot_st(sl_vm *vm, sl_value v) {
    if (AOT_UNLIKELY(v.type != SL_OBJ || !v.as.o || v.as.o->kind != SL_STRUCT)) AOT_FAIL("not a struct");
    return (sl_struct *)v.as.o;
}
static inline int64_t aot_index(sl_vm *vm, sl_arr *a, int64_t i) {
    int64_t k = i < 0 ? i + a->len : i;
    if (AOT_UNLIKELY(k < 0 || k >= a->len))
        AOT_FAIL("index %lld is out of bounds for an array of length %lld", (long long)i, (long long)a->len);
    return k;
}

static inline int64_t aot_len(sl_value v) {
    if (AOT_LIKELY(v.type == SL_OBJ && v.as.o && v.as.o->kind == SL_ARRAY)) return ((sl_arr *)v.as.o)->len;
    if (v.type == SL_OBJ && v.as.o) {
        if (v.as.o->kind == SL_STR) return utf8_length(v);
        if (v.as.o->kind == SL_MAP) return sl_map_len(v);
    }
    return sl_array_len(v);
}

static sl_value aot_concat(sl_vm *vm, sl_value a, sl_value b) {
    size_t an, bn;
    const char *ap = sl_as_str(a, &an), *bp = sl_as_str(b, &bn);
    sl_string *joined = str_alloc(vm, an + bn);
    if (!joined) longjmp(aot_jb, 1);
    memcpy(joined->bytes, ap, an);
    memcpy(joined->bytes + an, bp, bn);
    rel(vm, a); rel(vm, b);
    return obj_value(&joined->head);
}

static bool aot_streq(sl_vm *vm, sl_value a, sl_value b) {
    size_t an, bn;
    const char *ap = sl_as_str(a, &an), *bp = sl_as_str(b, &bn);
    bool eq = (an == bn) && memcmp(ap, bp, an) == 0;
    rel(vm, a); rel(vm, b);
    return eq;
}

static sl_value aot_str_i(sl_vm *vm, int64_t v) { return str_of_int(vm, v); }
static sl_value aot_str_f(sl_vm *vm, double v) {
    char tmp[64];
    fmt_float(tmp, sizeof tmp, v);
    return sl_str(vm, tmp, strlen(tmp));
}
static sl_value aot_str_b(sl_vm *vm, bool v) { return v ? sl_str(vm, "true", 4) : sl_str(vm, "false", 5); }

static sl_value aot_slice(sl_vm *vm, sl_value av, int64_t lo, int64_t hi) {
    sl_arr *a = aot_arr(vm, av);
    int64_t n = a->len, lo0 = lo, hi0 = hi;
    if (lo < 0) lo += n;
    if (hi < 0) hi += n;
    if (lo < 0 || hi > n || lo > hi)
        AOT_FAIL("slice [%lld:%lld] is out of bounds for an array of length %lld",
                 (long long)lo0, (long long)hi0, (long long)n);
    sl_value out = sl_array(vm, hi - lo);
    sl_arr *oa = (sl_arr *)out.as.o;
    for (int64_t k = lo; k < hi; k++) {
        sl_value item = arr_get(a, k);
        sl_retain(item);
        array_push(vm, oa, item);
    }
    rel(vm, av);
    return out;
}

static sl_value aot_newstruct(sl_vm *vm, uint16_t n, sl_value *items) {
    sl_struct *s = struct_alloc(vm, n);
    if (!s) AOT_FAIL("out of memory");
    s->head.rc = 1; s->head.kind = SL_STRUCT; s->nfields = n;
    for (uint16_t i = 0; i < n; i++) vstore(&s->fields[i], items[i]);
    vm->live++;
    return obj_value(&s->head);
}

static sl_value aot_newvar(sl_vm *vm, uint16_t tag, uint16_t n, sl_value *items) {
    sl_variant *t = (sl_variant *)malloc(sizeof(sl_variant) + (n ? n - 1 : 0) * sizeof(sl_value));
    if (!t) AOT_FAIL("out of memory");
    t->head.rc = 1; t->head.kind = SL_VARIANT; t->tag = tag; t->n = n;
    for (uint16_t i = 0; i < n; i++) vstore(&t->payload[i], items[i]);
    vm->live++;
    return obj_value(&t->head);
}

static int64_t aot_vtag(sl_vm *vm, sl_value v) {
    if (v.type != SL_OBJ || !v.as.o || v.as.o->kind != SL_VARIANT) AOT_FAIL("not an enum value");
    int64_t tag = ((sl_variant *)v.as.o)->tag;
    rel(vm, v);
    return tag;
}
static sl_value aot_vget(sl_vm *vm, sl_value v, uint16_t idx) {
    if (v.type != SL_OBJ || !v.as.o || v.as.o->kind != SL_VARIANT) AOT_FAIL("not an enum value");
    sl_variant *t = (sl_variant *)v.as.o;
    if (idx >= t->n) AOT_FAIL("bad payload index");
    sl_value e = vload(&t->payload[idx]);
    sl_retain(e);
    rel(vm, v);
    return e;
}

static sl_value aot_newmap(sl_vm *vm, uint16_t n, sl_value *items) {
    sl_value mv = sl_map(vm, n);
    for (uint16_t i = 0; i < n; i++)
        if (!sl_map_set(vm, mv, items[2 * i], items[2 * i + 1])) { rel(vm, mv); longjmp(aot_jb, 1); }
    return mv;
}
static sl_value aot_mget(sl_vm *vm, sl_value mv, sl_value kv) {
    if (mv.type != SL_OBJ || !mv.as.o || mv.as.o->kind != SL_MAP) AOT_FAIL("not a map");
    sl_value out;
    if (!sl_map_get(mv, kv, &out)) AOT_FAIL("key not found");
    sl_retain(out);
    rel(vm, kv); rel(vm, mv);
    return out;
}
// Base borrowed: the map stays owned by the caller's variable.
static sl_value aot_mget_b(sl_vm *vm, sl_value mv, sl_value kv) {
    if (AOT_UNLIKELY(mv.type != SL_OBJ || !mv.as.o)) AOT_FAIL("not a map");
    sl_value out;
    if (AOT_UNLIKELY(!sl_map_get(mv, kv, &out))) AOT_FAIL("key not found");
    sl_retain(out);
    rel(vm, kv);
    return out;
}
static void aot_mset_b(sl_vm *vm, sl_value mv, sl_value kv, sl_value val) {
    if (AOT_UNLIKELY(mv.type != SL_OBJ || !mv.as.o)) AOT_FAIL("not a map");
    if (!sl_map_set(vm, mv, kv, val)) longjmp(aot_jb, 1);
}
static void aot_mset(sl_vm *vm, sl_value mv, sl_value kv, sl_value val) {
    if (mv.type != SL_OBJ || !mv.as.o || mv.as.o->kind != SL_MAP) AOT_FAIL("not a map");
    if (!sl_map_set(vm, mv, kv, val)) longjmp(aot_jb, 1);
    rel(vm, mv);
}

static sl_value aot_native(sl_vm *vm, uint16_t idx, int argc, sl_value *argv) {
    int slot = vm->native_bind[idx];
    if (slot < 0) AOT_FAIL("`%s` is declared extern but the host did not register it", vm->native_names[idx]);
    sl_value result = vm->registry[slot].fn(vm, argc, argv);
    for (int i = 0; i < argc; i++) rel(vm, argv[i]);
    if (vm->failed) { rel(vm, result); longjmp(aot_jb, 1); }
    return result;
}

static sl_value aot_native_print(sl_vm *vm, int argc, sl_value *argv) {
    for (int i = 0; i < argc; i++) {
        if (i) printf(" ");
        sl_value s = sl_to_string(vm, argv[i]);
        size_t n;
        const char *p = sl_as_str(s, &n);
        fwrite(p, 1, n, stdout);
        sl_release(vm, s);
    }
    printf("\n");
    return sl_void();
}
